function getWeeklyOptionIds() {
  return NIFTY_WEEKLY_OPTIONS.map((opt) => opt.security_id);
}
function getWeeklyOptionIdsByStrike(atmStrike, range = 20) {
  const minStrike = atmStrike - range * 50;
  const maxStrike = atmStrike + range * 50;
  return NIFTY_WEEKLY_OPTIONS.filter((opt) => opt.strike >= minStrike && opt.strike <= maxStrike).map((opt) => opt.security_id);
}
